coration: none; }\ninput, select, textarea { width: 100%; border: 1px solid rgb(220, 225, 235); border-radius: 9px; outline: none; background: rgb(255, 255, 255); color: var(--ink); padding: 10px 11px; transition: border-color 150ms, box-shadow 150ms; }\ninput:focus, select:focus, textarea:focus { border-color: rgb(151, 140, 255); box-shadow: rgba(109, 93, 252, 0.1) 0px 0px 0px 3px; }\ninput:disabled, select:disabled, textarea:disabled { background: rgb(244, 245, 248); color: rgb(137, 147, 165); }\ntextarea { resize: vertical; }\nlabel, .field { display: grid; gap: 7px; color: rgb(88, 101, 121); font-size: 13px; font-weight: 700; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { border-bottom: 1px solid rgb(237, 240, 245); padding: 13px 14px; text-align: left; vertical-align: middle; }\nth { color: rgb(122, 133, 151); background: rgb(250, 251, 252); font-size: 12px; font-weight: 800; white-space: nowrap; }\ntd { color: rgb(66, 80, 102); font-size: 13px; }\n.app-shell { display: grid; grid-template-columns: 256px minmax(0px, 1fr); min-height: 100vh; }\n.app-shell--immersive { display: block; height: 100vh; min-height: 0px; overflow: hidden; }\n.app-shell--immersive > .app-sidebar, .app-shell--immersive > .app-workspace > .topbar { display: none; }\n.app-shell--immersive > .app-workspace, .app-shell--immersive .app-content--immersive { width: 100%; height: 100vh; min-height: 0px; }\n.app-sidebar { position: sticky; top: 0px; display: flex; flex-direction: column; height: 100vh; overflow-y: auto; border-right: 1px solid rgb(226, 232, 240); background: var(--sidebar); color: rgb(51, 65, 85); padding: 24px 18px 16px; }\n.brand { display: flex; align-items: center; gap: 11px; padding: 0px 6px; }\n.brand-mark { display: grid; width: 40px; height: 40px; place-items: center; border-radius: 10px; background: rgb(37, 99, 235); color: rgb(255, 255, 255); font-size: 14px; font-weight: 900; }\n.brand > span:last-child { display: grid; gap: 2px; }\n.brand strong { col