none; }\ninput, select, textarea { width: 100%; border: 1px solid rgb(220, 225, 235); border-radius: 9px; outline: none; background: rgb(255, 255, 255); color: var(--ink); padding: 10px 11px; transition: border-color 150ms, box-shadow 150ms; }\ninput:focus, select:focus, textarea:focus { border-color: rgb(151, 140, 255); box-shadow: rgba(109, 93, 252, 0.1) 0px 0px 0px 3px; }\ninput:disabled, select:disabled, textarea:disabled { background: rgb(244, 245, 248); color: rgb(137, 147, 165); }\ntextarea { resize: vertical; }\nlabel, .field { display: grid; gap: 7px; color: rgb(88, 101, 121); font-size: 13px; font-weight: 700; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { border-bottom: 1px solid rgb(237, 240, 245); padding: 13px 14px; text-align: left; vertical-align: middle; }\nth { color: rgb(122, 133, 151); background: rgb(250, 251, 252); font-size: 12px; font-weight: 800; white-space: nowrap; }\ntd { color: rgb(66, 80, 102); font-size: 13px; }\n.app-shell { display: grid; grid-template-columns: 256px minmax(0px, 1fr); min-height: 100vh; }\n.app-shell--immersive { display: block; height: 100vh; min-height: 0px; overflow: hidden; }\n.app-shell--immersive > .app-sidebar, .app-shell--immersive > .app-workspace > .topbar { display: none; }\n.app-shell--immersive > .app-workspace, .app-shell--immersive .app-content--immersive { width: 100%; height: 100vh; min-height: 0px; }\n.app-sidebar { position: sticky; top: 0px; display: flex; flex-direction: column; height: 100vh; overflow-y: auto; border-right: 1px solid rgb(226, 232, 240); background: var(--sidebar); color: rgb(51, 65, 85); padding: 24px 18px 16px; }\n.brand { display: flex; align-items: center; gap: 11px; padding: 0px 6px; }\n.brand-mark { display: grid; width: 40px; height: 40px; place-items: center; border-radius: 10px; background: rgb(37, 99, 235); color: rgb(255, 255, 255); font-size: 14px; font-weight: 900; }\n.brand > span:last-child { display: grid; gap: 2px; }\n.brand strong { color: rgb(23, 32, 51); font-size: 17px; }\n.brand small { color: rgb(148, 163, 184); font-size: 9px; font-weight: 800; letter-spacing: 0px; }\n.role-switcher { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin: 26px 0px 24px; padding: 5px; border: 1px solid rgb(226, 232, 240); border-radius: 8px; background: rgb(248, 250, 252); }\n.role-switcher button { display: grid; min-width: 0px; min-height: 52px; place-items: center; gap: 2px; border: 0px; border-radius: 6px; padding: 5px 2px; background: transparent; color: rgb(100, 116, 139); font-size: 10px; }\n.role-switcher button span { display: grid; width: 22px; height: 22px; place-items: center; border-radius: 6px; background: rgb(238, 242, 247); font-size: 11px; }\n.role-switcher button.active { background: rgb(255, 255, 255); color: rgb(29, 78, 216); box-shadow: none; }\n.role-switcher button.active span { background: var(--purple-soft); }\n.identity-card { display: grid; grid-template-columns: 34px minmax(0px, 1fr) 28px; min-height: 62px; align-items: center; gap: 9px; margin: 26px 0px 24px; border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 11px; padding: 9px; background: rgba(255, 255, 255, 0.04); }\n.identity-card > span { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 9px; color: rgb(217, 212, 255); background: rgba(116, 96, 239, 0.2); font-size: 12px; font-weight: 900; }\n.identity-card > div { display: grid; min-width: 0px; gap: 3px; }\n.identity-card small { color: rgb(116, 125, 148); font-size: 8px; }\n.identity-card strong { overflow: hidden; color: rgb(233, 235, 245); font-size: 11px; text-overflow: ellipsis; white-space: nowrap; }\n.identity-card > a { display: grid; width: 28px; height: 28px; place-items: center; border-radius: 7px; color: rgb(142, 151, 173); background: rgba(255, 255, 255, 0.05); font-size: 11px; }\n.identity-card > a:hover { color: rgb(255, 255, 255); background: rgba(255, 255, 255, 0.1); }\n.nav-caption { margin: 0px 10px 8px; color: rgb(148, 163, 184); font-size: 10px; font-weight: 800; letter-spacing: 0px; text-transform: uppercase; }\n.main-nav { display: grid; gap: 4px; }\n.main-nav a { display: flex; align-items: center; gap: 11px; min-height: 43px; border-radius: 6px; padding: 0px 11px; color: rgb(71, 85, 105); font-size: 13px; font-weight: 700; }\n.main-nav a:hover { background: rgb(241, 245, 249); color: rgb(23, 32, 51); }\n.main-nav a.router-link-active { background: rgb(239, 246, 255); color: rgb(29, 78, 216); }\n.main-nav a.router-link-active::after { width: 3px; height: 18px; margin-left: auto; border-radius: 4px; background: rgb(37, 99, 235); content: \"\"; }\n.nav-icon { display: grid; width: 24px; height: 24px; place-items: center; color: rgb(148, 163, 184); font-size: 11px; font-weight: 900; }\n.main-nav a.router-link-active .nav-icon { color: rgb(37, 99, 235); }\n.main-nav a.data-prepare-nav { min-height: 38px; margin-left: 10px; border-left: 2px solid rgb(219, 234, 254); border-radius: 0px 6px 6px 0px; padding-left: 12px; background: rgb(251, 253, 255); font-size: 12px; }\n.main-nav a.data-prepare-nav .nav-icon { width: 22px; height: 22px; border-radius: 6px; background: rgb(239, 246, 255); color: rgb(37, 99, 235); }\n.main-nav a.data-prepare-nav:hover { border-left-color: rgb(147, 197, 253); background: rgb(248, 251, 255); }\n.main-nav a.data-prepare-nav.router-link-active { border-left-color: rgb(37, 99, 235); background: rgb(239, 246, 255); }\n.sidebar-flow { display: grid; gap: 7px; margin-top: auto; border: 1px solid rgb(226, 232, 240); border-radius: 8px; background: rgb(248, 250, 252); padding: 13px; }\n.sidebar-flow__label { color: rgb(148, 163, 184); font-size: 10px; }\n.sidebar-flow strong { color: rgb(51, 65, 85); font-size: 12px; }\n.sidebar-flow small { color: rgb(100, 116, 139); font-size: 9px; line-height: 1.5; }\n.mini-progress { height: 4px; overflow: hidden; border-radius: 10px; background: rgb(226, 232, 240); }\n.mini-progress span { display: block; height: 100%; border-radius: inherit; background: rgb(37, 99, 235); }\n.sidebar-footer { display: grid; grid-template-columns: 34px minmax(0px, 1fr) auto; align-items: center; gap: 9px; margin-top: 14px; border-top: 1px solid rgb(226, 232, 240); padding: 14px 4px 0px; }\n.avatar { display: grid; width: 34px; height: 34px; place-items: center; border-radius: 50%; background: rgb(37, 99, 235); color: rgb(255, 255, 255); font-size: 12px; font-weight: 900; }\n.sidebar-footer > span:nth-child(2) { display: grid; gap: 2px; }\n.sidebar-footer strong { color: rgb(51, 65, 85); font-size: 11px; }\n.sidebar-footer small { color: rgb(100, 116, 139); font-size: 9px; }\n.sidebar-footer button { min-height: 28px; border: 0px; padding: 0px 5px; background: transparent; color: rgb(100, 116, 139); }\n.app-workspace { min-width: 0px; }\n.topbar { position: sticky; z-index: 20; top: 0px; display: flex; min-height: 72px; align-items: center; justify-content: space-between; gap: 20px; border-bottom: 1px solid rgb(234, 237, 243); background: rgba(255, 255, 255, 0.92); padding: 0px 28px; backdrop-filter: blur(14px); }\n.topbar > div:first-child { display: grid; gap: 4px; }\n.breadcrumb { color: rgb(152, 161, 177); font-size: 10px; }\n.topbar strong { font-size: 15px; }\n.topbar-actions { display: flex; align-items: center; gap: 9px; }\n.environment-badge { display: inline-flex; align-items: center; gap: 6px; border: 1px solid rgb(226, 222, 254); border-radius: 999px; padding: 6px 10px; color: rgb(98, 83, 213); background: rgb(247, 245, 255); font-size: 10px; font-weight: 800; }\n.environment-badge i { width: 6px; height: 6px; border-radius: 50%; background: rgb(109, 93, 252); box-shadow: rgba(109, 93, 252, 0.13) 0px 0px 0px 3px; }\n.platform-home-link { display: inline-flex; min-height: 30px; align-items: center; border: 1px solid rgb(226, 230, 237); border-radius: 8px; padding: 0px 10px; color: rgb(102, 114, 135); background: rgb(255, 255, 255); font-size: 10px; font-weight: 800; }\n.platform-home-link:hover { border-color: rgb(208, 202, 255); color: rgb(93, 78, 212); background: rgb(247, 245, 255); }\n.icon-button { display: grid; width: 34px; min-height: 34px; place-items: center; border-color: rgb(229, 232, 239); padding: 0px; color: rgb(102, 113, 135); }\n.today { margin-left: 4px; color: rgb(138, 147, 163); font-size: 11px; }\n.app-content { min-height: calc(-72px + 100vh); padding: 28px; }\n.app-content--immersive { overflow: hidden; padding: 0px; }\n.page { width: min(1500px, 100%); margin: 0px auto; }\n.page-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; margin-bottom: 24px; }\n.eyebrow { display: block; margin-bottom: 7px; color: var(--purple); font-size: 10px; font-weight: 900; letter-spacing: 0.14em; text-transform: uppercase; }\n.page-header h1 { margin: 0px; font-size: clamp(24px, 3vw, 32px); letter-spacing: -0.03em; }\n.page-header p { max-width: 760px; margin: 8px 0px 0px; color: var(--muted); font-size: 13px; line-height: 1.7; }\n.page-header__actions, .button-row, .inline-actions { display: flex; align-items: center; gap: 9px; flex-wrap: wrap; }\n.metric-grid { display: grid; grid-template-columns: repeat(4, minmax(0px, 1fr)); gap: 14px; }\n.metric-card { display: grid; grid-template-columns: 45px minmax(0px, 1fr); align-items: center; gap: 12px; border: 1px solid rgb(231, 234, 241); border-radius: 14px; background: rgb(255, 255, 255); padding: 17px; box-shadow: rgba(30, 36, 80, 0.04) 0px 8px 22px; }\n.metric-card__icon { display: grid; width: 43px; height: 43px; place-items: center; border-radius: 12px; color: rgb(102, 84, 231); background: rgb(240, 237, 255); }\n.metric-card.blue .metric-card__icon { color: rgb(38, 112, 216); background: rgb(234, 243, 255); }\n.metric-card.green .metric-card__icon { color: rgb(7, 133, 94); background: rgb(230, 248, 241); }\n.metric-card.amber .metric-card__icon { color: rgb(187, 113, 27); background: rgb(255, 243, 226); }\n.metric-card > div:last-child { display: grid; gap: 3px; }\n.metric-card span, .metric-card small { color: rgb(138, 148, 166); font-size: 10px; }\n.metric-card strong { font-size: 23px; }\n.card { border: 1px solid rgb(230, 233, 240); border-radius: 14px; background: rgb(255, 255, 255); box-shadow: rgba(30, 36, 80, 0.04) 0px 8px 24px; }\n.card-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-bottom: 1px solid rgb(238, 240, 245); padding: 16px 18px; }\n.card-header h2, .card-header h3 { margin: 0px; font-size: 15px; }\n.card-header p { margin: 5px 0px 0px; color: rgb(138, 148, 166); font-size: 11px; }\n.card-body { padding: 18px; }\n.content-grid { display: grid; grid-template-columns: minmax(0px, 1.7fr) minmax(280px, 0.8fr); gap: 16px; margin-top: 16px; }\n.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 15px; }\n.form-grid.three { grid-template-columns: repeat(3, minmax(0px, 1fr)); }\n.field.wide { grid-column: 1 / -1; }\n.table-wrap { overflow-x: auto; }\n.table-wrap table { min-width: 760px; }\n.status-pill { display: inline-flex; width: fit-content; align-items: center; border-radius: 999px; padding: 4px 8px; color: rgb(104, 115, 134); background: rgb(238, 241, 245); font-size: 10px; font-weight: 800; }\n.status-pill.success { color: rgb(13, 132, 95); background: rgb(230, 248, 241); }\n.status-pill.warning { color: rgb(165, 103, 29); background: rgb(255, 243, 222); }\n.status-pill.danger { color: rgb(189, 63, 74); background: rgb(255, 237, 239); }\n.empty-state { display: grid; min-height: 260px; place-items: center; padding: 40px; color: rgb(132, 144, 163); text-align: center; }\n.empty-state strong { color: rgb(82, 96, 119); }\n.notice { margin: 14px 0px; border: 1px solid rgb(220, 216, 255); border-radius: 10px; padding: 11px 13px; color: rgb(98, 83, 213); background: rgb(248, 247, 255); font-size: 12px; }\n.notice.success { border-color: rgb(198, 236, 221); color: rgb(8, 123, 89); background: rgb(240, 251, 247); }\n.notice.danger { border-color: rgb(255, 210, 214); color: rgb(180, 58, 70); background: rgb(255, 245, 245); }\n.dialog-backdrop { position: fixed; z-index: 100; inset: 0px; display: grid; place-items: center; padding: 20px; background: rgba(16, 20, 38, 0.48); backdrop-filter: blur(5px); }\n.dialog { width: min(640px, 96vw); max-height: 92vh; overflow-y: auto; border-radius: 16px; background: rgb(255, 255, 255); box-shadow: rgba(15, 19, 40, 0.28) 0px 30px 80px; }\n.dialog-header, .dialog-footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 17px 20px; }\n.dialog-header { border-bottom: 1px solid rgb(236, 238, 243); }\n.dialog-header h2 { margin: 0px; font-size: 18px; }\n.dialog-body { padding: 20px; }\n.dialog-footer { justify-content: flex-end; border-top: 1px solid rgb(236, 238, 243); }\n.standalone-state { display: grid; min-height: 100vh; place-items: center; align-content: center; gap: 10px; padding: 30px; color: rgb(101, 112, 134); text-align: center; }\n.standalone-state > span { color: var(--purple); font-size: 74px; font-weight: 900; }\n.standalone-state h1, .standalone-state p { margin: 0px; }\n.standalone-state .button { display: inline-flex; align-items: center; margin-top: 12px; }\n@media (max-width: 1180px) {\n  .metric-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }\n  .content-grid { grid-template-columns: 1fr; }\n  .today { display: none; }\n}\n@media (max-width: 820px) {\n  .app-shell { grid-template-columns: 1fr; }\n  .app-sidebar { position: static; height: auto; min-height: 0px; }\n  .main-nav { grid-template-columns: repeat(3, minmax(0px, 1fr)); }\n  .main-nav a { justify-content: center; }\n  .main-nav a.router-link-active::after, .sidebar-flow, .sidebar-footer, .main-nav a > span:last-child { display: none; }\n  .role-switcher { margin-bottom: 14px; }\n  .topbar { position: static; padding: 0px 18px; }\n  .app-content { padding: 20px 16px; }\n  .app-content--immersive { padding: 0px; }\n  .p